import{_ as c,a8 as t,o as r,c as g,ah as b,a,a3 as o,K as d,L as n}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const w=JSON.parse('{"title":"博客（E:\\\\knowledge VitePress）构建与部署踩坑","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-14T00:00:00.000Z","tags":["VitePress","构建","部署","CI","调试","安全"]},"headers":[],"relativePath":"vault/Memory/Lessons/博客构建与部署踩坑.md","filePath":"vault/Memory/Lessons/博客构建与部署踩坑.md","lastUpdated":1789374053000}'),m={name:"vault/Memory/Lessons/博客构建与部署踩坑.md"};function u(h,e,p,_,k,f){const s=t("VPNolebaseInlineLinkPreview"),l=t("NolebaseGitContributors"),i=t("NolebaseGitChangelog");return r(),g("div",null,[e[4]||(e[4]=b('<h1 id="博客-e-knowledge-vitepress-构建与部署踩坑" tabindex="-1">博客（E:\\knowledge VitePress）构建与部署踩坑 <a class="header-anchor" href="#博客-e-knowledge-vitepress-构建与部署踩坑" aria-label="Permalink to “博客（E:\\knowledge VitePress）构建与部署踩坑”">​</a></h1><blockquote><p>提炼自 2026-07 整月构建/部署调试日志，供后续改博客时复用。</p></blockquote><h2 id="⚠️-安全事项-最高优先级" tabindex="-1">⚠️ 安全事项（最高优先级） <a class="header-anchor" href="#⚠️-安全事项-最高优先级" aria-label="Permalink to “⚠️ 安全事项（最高优先级）”">​</a></h2><ul><li><strong>腾讯云密钥曾明文入库</strong>：<code>vault/Knowledge/Engineering/Django 项目实战.md</code> 含真实 SecretId/SecretKey（本行引用已脱敏，前缀 AKID）。已脱敏为占位符并推库，但<strong>云端凭证本身可能已泄露</strong>。教训：记录密钥泄露事件的笔记自身也必须脱敏，勿把真钥再抄一遍。</li><li><strong>行动项</strong>：去腾讯云轮换（吊销并重发）该 SecretId/Key。仓库内容已脱敏、部署不会重暴露，但轮换是独立待办。</li></ul><h2 id="构建崩溃类" tabindex="-1">构建崩溃类 <a class="header-anchor" href="#构建崩溃类" aria-label="Permalink to “构建崩溃类”">​</a></h2><ul><li><strong>thumbnail-hash 全量扫描仓库根崩溃</strong>：<code>@nolebase/vitepress-plugin-thumbnail-hash</code> 的 <code>ThumbnailHashImages</code> 插件 <code>glob(&quot;${root}/**/*.{jpg,...}&quot;)</code> 扫整个仓库（含 834 张未发布 Attachments + node_modules），逐张 Skia 解码 → 卡死/2.7GB+ 内存。<strong>修法</strong>：<code>vite.config.ts</code> 的 <code>presetVite()</code> 加 <code>thumbnailHashImages:false</code>（站点用 <code>obsidian-image-embed</code> 渲染普通 <code>&lt;img&gt;</code>，关闭零副作用）。注意该插件有 vite 侧（生成 map.json）与 markdown-it 侧（unlazyImages，须读到 map.json）两个独立部分，只关一边另一边会报 <code>No thumbhash map file found</code>——<strong>两边都要关</strong>（<code>presetMarkdownIt({unlazyImages:false})</code>）。</li><li><strong>nolebase 双前缀 <code>/knowledge/knowledge/</code></strong>：原 <code>baseDir:&#39;/knowledge/&#39;</code> 让 nolebase 先产 <code>/knowledge/vault/...</code>，VitePress 再叠一次 base → 双前缀、全部 404。<strong>修法：<code>baseDir</code> 必须设为根 <code>/</code></strong>，只输出 <code>/vault/...</code>，由 VitePress 补一次 base。</li><li><strong>根路径重定向到废弃 <code>/zh-CN/</code></strong>：VitePress 2.0 alpha i18n 把默认语言算成 <code>lang</code> 值（<code>zh-CN</code>）而非内容目录 <code>/vault</code>，向每个页面内联注入跳 <code>/knowledge/zh-CN/</code> 的重定向脚本。<strong>修法</strong>：<code>config.ts</code> 的 <code>buildEnd</code> 钩子写根 <code>index.html</code> 跳 <code>/knowledge/vault/</code> + 递归把全站 HTML 内联脚本 <code>/knowledge/zh-CN/</code>→<code>/knowledge/vault/</code> + <code>&lt;html dir=&quot;/vault&quot;&gt;</code>→<code>dir=&quot;ltr&quot;</code>。</li><li><strong>URIError（文件名含 <code>%</code>）</strong>：<code>vault/Knowledge/Methods/300%法则.md</code> 文件名含字面 <code>%</code> → VitePress sidebar <code>decodeURI</code> 与页面 <code>decodeURIComponent</code> 双崩溃。<strong>修法</strong>：文件系统改名去 <code>%</code>（概念保留在 H1/正文）；链接路径防御性 <code>%</code>→<code>%25</code> 编码。</li><li><strong>OOM exit 134</strong>：全量构建（Knowledge 227 页 + nolebase 扫 1910 文件建索引）吃穿默认 4GB 堆。<code>build.mjs</code> 仅当 <code>NODE_OPTIONS</code> 未设才补 8GB，若环境已钉 4GB 则兜底被跳过。<strong>修法</strong>：运行前 <code>unset NODE_OPTIONS</code> 或显式 <code>NODE_OPTIONS=--max-old-space-size=8192</code>（CI 用 6144）。</li></ul><h2 id="本地沙箱-git-类" tabindex="-1">本地沙箱 / Git 类 <a class="header-anchor" href="#本地沙箱-git-类" aria-label="Permalink to “本地沙箱 / Git 类”">​</a></h2><ul><li><strong>WorkBuddy 沙箱 safe-delete 守卫</strong>：清 <code>dist/assets</code> 超 50 文件被拦、后续 <code>&amp;&amp; build</code> 不执行，表现&quot;build complete 却无 HTML&quot;。<strong>绕过（仅本地沙箱）</strong>：<code>CODEBUDDY_SAFE_DELETE_BULK_STATE_DIR= CODEBUDDY_TOOL_CALL_ID= pnpm docs:build</code>；<strong>勿</strong>把该特例写进 <code>package.json</code>（污染公开仓库）。正确做法是用 <code>pnpm docs:build</code>（VitePress 自己清 outDir），不要手动 <code>rm -rf .vitepress/dist</code>。</li><li><strong>push 被拒 324MB 视频</strong>：<code>.gitignore</code> 在首次 <code>git add</code> 同刻才位，挡不住已进历史的 blob；<code>git push</code> 被 GH001 拒。<strong>修法</strong>：<code>git filter-branch --index-filter</code> 重写未推送提交、只留被引用的 39 张图（其余视频/压缩包剥离）+ pre-commit 加 &gt;100MB 护栏。教训：私人目录 <code>.gitignore</code> 必须在<strong>首次 <code>git add</code> 之前</strong>就位；千万别 <code>git add -A</code>。</li><li><strong>模拟 CI 干净构建必须删 <code>.vitepress/cache</code></strong>：本地缓存会掩盖 CI 才暴露的 thumbhash/重定向问题。</li></ul><h2 id="图片渲染根因-obsidian-image-embed" tabindex="-1">图片渲染根因（obsidian-image-embed） <a class="header-anchor" href="#图片渲染根因-obsidian-image-embed" aria-label="Permalink to “图片渲染根因（obsidian-image-embed）”">​</a></h2><ul><li>nolebase 双向链接内联规则 <code>bi_directional_link_replace</code>（<code>ruler.after(&#39;text&#39;)</code> 注册）会<strong>抢先吃掉 <code>![[...]]</code></strong>，导致 Obsidian 双链图片不渲染。原插件 <code>before(&#39;link&#39;)</code> 锚定排在 nolebase 之后永不发生。修法见沉淀 skill <code>vitepress-obsidian-image-embed</code>。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2>',11)),a("ul",null,[a("li",null,[e[2]||(e[2]=o("项目概况见 ",-1)),d(s,{class:"route-link nolebase-route-link-invalid",href:"#",target:"_target"},{default:n(()=>[...e[0]||(e[0]=[o("knowledge-blog",-1)])]),_:1}),e[3]||(e[3]=o("；技术决策见 ",-1)),d(s,{href:"/knowledge/vault/Memory/Decisions/knowledge-blog技术决策.html"},{default:n(()=>[...e[1]||(e[1]=[o("knowledge-blog技术决策",-1)])]),_:1})])]),d(l),d(i)])}const I=c(m,[["render",u]]);export{w as __pageData,I as default};
